use gielinor_client::{disk_cache::DiskCache,animation::Skeleton,cached_animation::CachedAnimation};use std::io::Write;
fn main()->Result<(),Box<dyn std::error::Error>>{let a=std::env::args().collect::<Vec<_>>();let mut c=DiskCache::open(&a[1],64<<20)?;let ids=c.reference(22)?.groups.iter().map(|g|g.id).collect::<Vec<_>>();let mut skeletons=std::collections::HashMap::new();let(mut count,mut channels,mut keys,mut weighted)=(0,0,0,0);let mut samples=Vec::new();let mut faults=0;
for id in ids{for(file,data)in c.group(22,id,[0;4])?{let sid=u16::from_be_bytes(data[1..3].try_into().unwrap());if !skeletons.contains_key(&sid){skeletons.insert(sid,c.file(1,sid as u32,0,[0;4])?);}let skeleton=Skeleton::decode(sid,&skeletons[&sid])?;let anim=match CachedAnimation::decode(&data,&skeleton){Ok(a)=>a,Err(e)=>{faults+=1;eprintln!("cached {id}:{file}: {e}");continue;}};count+=1;channels+=anim.channels.len();for channel in &anim.channels{keys+=channel.curve.keys.len();weighted+=channel.curve.weighted as usize;}if count%19==1{samples.push((id<<16|file,data,skeletons[&sid].clone()));}}}
let mut out=std::fs::File::create(&a[2])?;out.write_all(&(samples.len() as u32).to_be_bytes())?;for(id,data,skeleton)in samples{out.write_all(&id.to_be_bytes())?;for bytes in [data,skeleton]{out.write_all(&(bytes.len() as u32).to_be_bytes())?;out.write_all(&bytes)?;}}println!("Decoded {count} cached animations, {channels} channels ({weighted} weighted), {keys} keys; {faults} failures");if faults>0{return Err("cached animation failures".into());}Ok(())}
